<template>
  <div class="marketplace-console"><el-card shadow="never"><h1 class="marketplace-heading">商品审核</h1><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="marketplace-feedback" /><el-alert v-if="notice" :title="notice" role="status" aria-live="polite" type="success" :closable="false" show-icon class="marketplace-feedback" /><div class="marketplace-toolbar"><label for="platform-product-merchant-filter">商家</label><el-select id="platform-product-merchant-filter" aria-label="商品所属商家" v-model="merchantId" placeholder="全部商家" filterable clearable :disabled="loading || busy || !can('marketplace-merchants-list')"><el-option v-for="merchant in merchants" :key="merchant.mer_id" :value="merchant.mer_id" :label="merchant.name + '（' + merchant.mer_id + '）'" /></el-select><label for="platform-product-review-filter">审核状态</label><el-select id="platform-product-review-filter" aria-label="商品审核状态" v-model="reviewStatus" :disabled="loading || busy"><el-option v-for="(label, index) in statuses" :key="index" :value="index" :label="label" /></el-select><el-button :disabled="loading || busy" @click="search">查询</el-button></div><p v-if="!can('marketplace-merchants-list')">当前账号无商家列表权限，显示全部已授权商品审核列表。</p>
    <el-table v-loading="loading" :data="rows" border><el-table-column prop="id" label="商品编号" width="105" /><el-table-column label="商品" min-width="230"><template slot-scope="scope"><div class="marketplace-product-name"><img :src="scope.row.image" class="marketplace-image" alt="商品图片"><span>{{ scope.row.store_name }}</span></div></template></el-table-column><el-table-column label="商家" min-width="160"><template slot-scope="scope">{{ merchantName(scope.row.mer_id) }}</template></el-table-column><el-table-column prop="price" label="售价（元）" width="115" /><el-table-column label="审核状态" width="120"><template slot-scope="scope">{{ statuses[scope.row.review_status] }}</template></el-table-column><el-table-column label="上架状态" width="110"><template slot-scope="scope">{{ scope.row.is_show ? '已上架' : '未上架' }}</template></el-table-column><el-table-column label="操作" min-width="185"><template slot-scope="scope"><div class="marketplace-actions"><el-button v-if="can('marketplace-products-review') && scope.row.review_status === 1 && knownMerchant(scope.row.mer_id)" size="mini" :disabled="busy" :aria-label="'审核通过商品 ' + scope.row.store_name" @click="act('approve', scope.row)">审核通过</el-button><el-button v-if="can('marketplace-products-review') && [1,3].includes(scope.row.review_status) && knownMerchant(scope.row.mer_id)" size="mini" :disabled="busy" :aria-label="'驳回商品 ' + scope.row.store_name" @click="openReject(scope.row)">{{ scope.row.review_status === 3 ? '修改驳回原因' : '驳回' }}</el-button><el-button v-if="can('marketplace-products-off-shelf') && scope.row.is_show === 1 && knownMerchant(scope.row.mer_id)" size="mini" :disabled="busy" :aria-label="'下架商品 ' + scope.row.store_name" @click="act('off', scope.row)">下架</el-button></div></template></el-table-column></el-table><div class="marketplace-pagination"><el-pagination :current-page="page" :page-size="limit" :pager-count="5" :total="count" layout="prev, pager, next" @current-change="changePage" /></div></el-card><el-dialog title="人工驳回商品" :visible.sync="rejectVisible" width="min(94vw, 640px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeReject"><p v-if="rejectTarget" class="marketplace-note">商品：{{ rejectTarget.store_name }}（{{ rejectTarget.id }}）<br>商家：{{ merchantName(rejectTarget.mer_id) }}<br>当前状态：{{ statuses[rejectTarget.review_status] }}</p><el-alert v-if="rejectError" :title="rejectError" type="error" :closable="false" show-icon /><el-form label-position="top" @submit.native.prevent="rejectProduct"><el-form-item label="驳回原因" for="platform-product-reject-reason" required><el-input id="platform-product-reject-reason" label="商品驳回原因" v-model="rejectReason" type="textarea" :rows="5" maxlength="512" :disabled="busy" /></el-form-item><div class="marketplace-actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="busy">确认驳回此商品</el-button><el-button :disabled="busy" @click="rejectVisible = false">取消</el-button></div></el-form></el-dialog></div>
</template>
<script>
import { marketplaceApi as api, marketplaceError } from '@/api/marketplace';
import { platformCan } from '@/libs/marketplace-navigation';
import '../style.css';
export default {
  name: 'marketplaceProducts', data: () => ({ merchants: [], merchantId: '', reviewStatus: 1, page: 1, limit: 20, rows: [], count: 0, statuses: ['草稿', '待审核', '审核通过', '已驳回'], loading: false, busy: false, error: '', notice: '', rejectVisible: false, rejectTarget: null, rejectReason: '', rejectError: '' }),
  created() { this.initialize(); },
  methods: {
    can(permission) { return platformCan(this.$store, permission); }, knownMerchant(id) { return Number.isInteger(id) && id > 0; }, merchantName(id) { const row = this.merchants.find((merchant) => merchant.mer_id === id); return row ? row.name : id === null || id === 0 ? '归属待确认' : '商家 ' + id; },
    async initialize() { this.loading = true; this.error = ''; try { if (this.can('marketplace-merchants-list')) { let page = 1, count; const rows = []; do { const data = await api.merchants({ page, limit: 100 }); if (!data || !Array.isArray(data.list) || !Number.isInteger(data.count)) throw new Error('商家筛选列表返回不完整'); rows.push(...data.list); count = data.count; if (!data.list.length && rows.length < count) throw new Error('商家筛选列表不完整'); page += 1; } while (rows.length < count); this.merchants = rows; } } catch (error) { this.error = marketplaceError(error); this.loading = false; return; } this.loading = false; this.load(); },
    search() { this.page = 1; this.load(); }, changePage(page) { if (!this.loading && !this.busy) { this.page = page; this.load(); } },
    async load(propagate = false) { if (this.loading) { if (propagate === true) throw new Error('列表仍在读取，请稍后刷新'); return; } this.loading = true; this.error = ''; try { const query = { review_status: this.reviewStatus, page: this.page, limit: this.limit }; if (this.merchantId !== '') { const merchant = this.merchants.find((row) => row.mer_id === this.merchantId); if (!merchant) throw new Error('请选择当前实际商家'); query.mer_id = merchant.mer_id; } const data = await api.products(query); if (!data || !Array.isArray(data.list) || !Number.isInteger(data.count)) throw new Error('商品审核列表返回不完整'); this.rows = data.list; this.count = data.count; } catch (error) { this.error = marketplaceError(error); if (propagate === true) throw error; } finally { this.loading = false; } },
    async readState(id, merId, reviewStatus) {
      let page = 1, count;
      do {
        const data = await api.products({ review_status: reviewStatus, mer_id: merId, page, limit: 100 });
        if (!data || !Array.isArray(data.list) || !Number.isInteger(data.count)) throw new Error('商品状态列表返回不完整');
        const actual = data.list.find((row) => row.id === id && row.mer_id === merId); if (actual) return actual;
        count = data.count; page += 1;
      } while ((page - 1) * 100 < count);
      throw new Error('商品状态重新读取未找到当前商品');
    },
    closeReject(done) { if (!this.busy) done(); },
    openReject(row) { if (this.busy || this.loading) return; this.rejectTarget = row; this.rejectReason = row.review_reason; this.rejectError = ''; this.rejectVisible = true; },
    async rejectProduct() {
      if (this.busy) return; this.rejectError = ''; this.notice = ''; const reason = this.rejectReason.trim(); if (!reason) { this.rejectError = '请填写实际驳回原因'; return; }
      const target = this.rejectTarget; this.busy = true; let committed = false;
      try {
        const returned = await api.rejectProduct(target.id, reason); committed = true;
        if (!returned || returned.id !== target.id || returned.mer_id !== target.mer_id || returned.review_status !== 3 || returned.is_show !== 0) throw new Error('驳回状态响应未确认');
        const actual = await this.readState(target.id, target.mer_id, 3); if (actual.review_status !== 3 || actual.is_show !== 0 || actual.review_reason !== reason) throw new Error('驳回状态或理由重新读取未确认');
        await this.load(true); this.rejectVisible = false; this.rejectTarget = null; this.rejectReason = ''; this.notice = '商品“' + actual.store_name + '”已驳回，状态和理由已重新读取';
      } catch (error) { this.rejectError = (committed ? '驳回已提交，重新读取或列表刷新未完成：' : '') + marketplaceError(error); }
      finally { this.busy = false; }
    },
    async act(kind, row) { if (this.busy || this.loading) return; this.busy = true; this.error = ''; this.notice = ''; let changed = false; try { const actual = kind === 'approve' ? await api.approveProduct(row.id) : await api.offShelf(row.id); changed = true; if (!actual || actual.id !== row.id || actual.mer_id !== row.mer_id || !Number.isInteger(actual.review_status) || !Number.isInteger(actual.is_show) || (kind === 'approve' && actual.review_status !== 2) || (kind === 'off' && actual.is_show !== 0)) throw new Error('商品状态返回不完整，请重新读取'); const reread = await this.readState(row.id, row.mer_id, actual.review_status); if (reread.review_status !== actual.review_status || reread.is_show !== actual.is_show) throw new Error('商品状态重新读取未确认'); await this.load(true); this.notice = kind === 'approve' ? '商品审核已完成，当前状态：' + this.statuses[actual.review_status] : '商品已下架'; } catch (error) { this.error = (changed ? '操作已提交，状态或列表核对未完成：' : '') + marketplaceError(error); } finally { this.busy = false; } },
  },
};
</script>
